r_template:
local({
  {{#each target_vars}}
  v <- .active_data[[ '{{this}}' ]]
  if ({{../chk_stats}} && is.numeric(v)) {
    stats_df <- data.frame(
      N = sum(!is.na(v)),
      Mean = mean(v, na.rm = TRUE),
      Std_Dev = sd(v, na.rm = TRUE),
      Min = min(v, na.rm = TRUE),
      Max = max(v, na.rm = TRUE)
    )
    rrad_emit_table(stats_df, title = paste('Descriptive Statistics:', '{{this}}'))
  }
  if ({{../chk_tables}}) {
    freq_tb <- as.data.frame(table(v, useNA = 'ifany'))
    names(freq_tb) <- c('Value', 'Frequency')
    freq_tb$Percent <- round((freq_tb$Frequency / sum(freq_tb$Frequency)) * 100, 1)
    rrad_emit_table(freq_tb, title = paste('Frequencies:', '{{this}}'))
  }
  {{/each}}
})
